import{_ as a,o,c as t,a2 as r}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Backups And Restore","description":"","frontmatter":{"title":"Backups And Restore"},"headers":[],"relativePath":"operations/backups-and-restore.md","filePath":"operations/backups-and-restore.md","lastUpdated":1787839527000}'),l={name:"operations/backups-and-restore.md"};function s(c,e,d,i,n,p){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="backups-and-restore" tabindex="-1">Backups-And-Restore <a class="header-anchor" href="#backups-and-restore" aria-label="Permalink to &quot;Backups-And-Restore&quot;">​</a></h1><h2 id="目的" tabindex="-1">目的 <a class="header-anchor" href="#目的" aria-label="Permalink to &quot;目的&quot;">​</a></h2><p>把 collab-store 的備份/還原流程固化成可執行 runbook，避免「備份不完整或還原步驟不一致」造成不可逆資料遺失。</p><h2 id="備份-collab-store-sqlite" tabindex="-1">備份（collab-store sqlite） <a class="header-anchor" href="#備份-collab-store-sqlite" aria-label="Permalink to &quot;備份（collab-store sqlite）&quot;">​</a></h2><ul><li><code>backend &amp;&amp; npm run backup:collab</code></li></ul><p>備份的「唯一耐久來源」是：</p><ul><li><code>backend/.server-data/collab-store.sqlite</code></li><li>production volume：<code>/mnt/data/Data/serviceApps/StrawMB/.server-data/collab-store.sqlite</code></li></ul><p>執行後會產出：</p><ul><li><code>.server-data/backups/collab-store-YYYYMMDDTHHMMSSZ.sqlite</code> 並保留最新 <code>SHARED_LEDGER_BACKUP_KEEP</code>（預設 14）份。</li></ul><h2 id="還原演練-restore-drill" tabindex="-1">還原演練（Restore drill） <a class="header-anchor" href="#還原演練-restore-drill" aria-label="Permalink to &quot;還原演練（Restore drill）&quot;">​</a></h2><p>依 <code>docs/backup-strategy.md</code> 的步驟：</p><ol><li>停止寫入：例如 <code>docker stop StrawMB</code>（或同等停止 API/容器寫入）</li><li>置換壞檔：<code>mv collab-store.sqlite collab-store.sqlite.broken</code></li><li>用備份覆蓋：<code>cp backups/collab-store-&lt;stamp&gt;.sqlite collab-store.sqlite</code></li><li>驗證可打開且完整性正常：<code>sqlite3 collab-store.sqlite &#39;PRAGMA integrity_check; SELECT COUNT(*) FROM users;&#39;</code></li><li>啟動 API 並驗證：<code>docker start StrawMB</code>、<code>GET /health</code>、登入並開啟至少一個 shared ledger</li></ol><blockquote><p>原則：不要在 API 還持有檔案時做 Restore；也不要把 <code>SHARED_LEDGER_DB_FILE</code> 直接指向備份檔原地覆寫（避免下一輪備份 prune 把「活檔」一起刪掉）。</p></blockquote><h2 id="引用來源" tabindex="-1">引用來源 <a class="header-anchor" href="#引用來源" aria-label="Permalink to &quot;引用來源&quot;">​</a></h2><ul><li><a href="https://github.com/StrawCoding/StrawMoneyBook/blob/main/docs/backup-strategy.md" target="_blank" rel="noreferrer"><code>docs/backup-strategy.md</code></a></li><li><a href="https://github.com/StrawCoding/StrawMoneyBook/blob/main/docs/google-backend-auth.md" target="_blank" rel="noreferrer"><code>docs/google-backend-auth.md</code></a>（若還原後涉及驗證/授權排查）</li></ul>',15)])])}const h=a(l,[["render",s]]);export{u as __pageData,h as default};
